async handleSubmit(event) {
    event.preventDefault();
    this.clearMessages();

    if (!this.validateAll()) {
        return;
    }

    this.isSubmitting = true;

    try {
        // Prepare data for automation
        const formData = {
            name: this.form.name.trim(),
            email: this.form.email.trim(),
            subject: this.form.subject,
            message: this.form.message.trim(),
            source: 'Website Contact Form',
            timestamp: new Date().toISOString()
        };

        // Send to Zapier webhook (You'll need to create this webhook in Zapier)
        // For now, we'll use FormSubmit as primary and prepare for Zapier
        const zapierWebhookUrl = window.ZAPIER_WEBHOOK_URL || null;

        if (zapierWebhookUrl) {
            // Send to Zapier for automation
            fetch(zapierWebhookUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(formData)
            }).catch(err => console.log('Zapier webhook failed:', err));
        }

        // Send to FormSubmit as primary/backup
        const formSubmitData = new FormData(event.target);
        const response = await fetch(event.target.action, {
            method: 'POST',
            body: formSubmitData
        });

        if (response.ok || response.type === 'opaque') {
            this.showSuccess = true;

            // Reset form after short delay
            setTimeout(() => {
                this.resetForm();
                // Redirect to thank you page
                window.location.href = '/contact/thank-you/';
            }, 1500);
        } else {
            throw new Error('Form submission failed');
        }
    } catch (error) {
        console.error('Form submission error:', error);
        this.showError = true;
    } finally {
        this.isSubmitting = false;
    }
},

